import uuid
import time

class Request:
    def __init__(self, data):
        self.id = uuid.uuid4()  # Unique request ID
        self.data = data
        self.status = "pending"
        self.timestamp = time.time()

    def __repr__(self):
        return f"Request(id={self.id}, status={self.status})"


class Pipe:
    def __init__(self, name, processing_function):
        self.name = name
        self.processing_function = processing_function

    def process(self, request):
        try:
            self.processing_function(request)
            request.status = "processed by " + self.name
            return request
        except Exception as e:
            request.status = "failed in " + self.name + f": {e}"
            return request


class Payment:
    def __init__(self, amount, payment_function):
        self.amount = amount
        self.payment_function = payment_function

    def process(self, request):
        try:
            if self.payment_function(request):
                request.status = "payment successful"
                return request
            else:
                request.status = "payment failed"
                return request
        except Exception as e:
            request.status = "payment error: " + str(e)
            return request


class RequestProcessor:
    def __init__(self):
        self.pipes = []
        self.payment = None

    def add_pipe(self, pipe):
        self.pipes.append(pipe)

    def set_payment(self, payment):
        self.payment = payment

    def process_request(self, request):
        current_request = request
        for pipe in self.pipes:
            current_request = pipe.process(current_request)

        if self.payment:
            current_request = self.payment.process(current_request)

        return current_request


