```javascript
const table = document.querySelector('.table');

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    sortTable(table, event.target.dataset.sort);
  }
});

function sortTable(table, sortType) {
  const tbody = table.querySelector('tbody');
  const rows = Array.from(tbody.querySelectorAll('tr'));

  // Get the header that was clicked
  const header = event.target;
  const columnIndex = Array.from(header.parentNode.children).indexOf(header);

  // Sort the rows
  rows.sort((a, b) => {
    const cellA = a.querySelectorAll('td')[columnIndex].textContent;
    const cellB = b.querySelectorAll('td')[columnIndex].textContent;

    switch (sortType) {
      case 'string':
        return cellA.localeCompare(cellB);
      case 'number':
        return parseFloat(cellA) - parseFloat(cellB);
      case 'date':
        return new Date(cellA) - new Date(cellB);
      default:
        return 0; // No sorting
    }
  });

  // Clear the table body and append the sorted rows
  tbody.innerHTML = '';
  rows.forEach(row => tbody.appendChild(row));
}
```

